import java.io.*;
import java.util.*;

// ---- 1. 标准装饰器骨架 ----
interface DataSource {
    String readData();
    void writeData(String data);
}

class FileDataSource implements DataSource {
    private final String filename;
    FileDataSource(String filename) { this.filename = filename; }
    public String readData() { return "[raw from " + filename + "]"; }
    public void writeData(String data) { System.out.println("Write: " + data); }
}

// 装饰器基类：实现接口 + 持有引用 + 默认转调
abstract class DataSourceDecorator implements DataSource {
    protected final DataSource wrappee;  // 持有被装饰对象引用
    DataSourceDecorator(DataSource wrappee) { this.wrappee = wrappee; }
    public String readData() { return wrappee.readData(); }
    public void writeData(String data) { wrappee.writeData(data); }
}

// 具体装饰器：加密
class EncryptionDecorator extends DataSourceDecorator {
    EncryptionDecorator(DataSource wrappee) { super(wrappee); }
    public String readData() {
        String data = wrappee.readData();
        return "[decrypted:" + data + "]";  // 解密后返回
    }
    public void writeData(String data) {
        wrappee.writeData("[encrypted:" + data + "]");  // 加密后写入
    }
}

// 具体装饰器：压缩
class CompressionDecorator extends DataSourceDecorator {
    CompressionDecorator(DataSource wrappee) { super(wrappee); }
    public String readData() {
        String data = wrappee.readData();
        return "[decompressed:" + data + "]";
    }
    public void writeData(String data) {
        wrappee.writeData("[compressed:" + data + "]");
    }
}

// ---- 2. 运行时组合 ----
public class Demo {
    public static void main(String[] args) {
        // 基础组件
        DataSource source = new FileDataSource("data.txt");

        // 先压缩再加密（顺序有意义！）
        DataSource wrapped = new EncryptionDecorator(
                                new CompressionDecorator(source));
        wrapped.writeData("Hello");
        // 输出链: Write: [encrypted:[compressed:Hello]]

        // ---- 3. Java IO 的等价写法 ----
        InputStream is = new BufferedInputStream(  // 缓冲装饰器
                            new FileInputStream("file.txt"));

        // ---- 4. Collections 包装 ----
        List<String> list = new ArrayList<>();
        List<String> sync = Collections.synchronizedList(list);  // 同步装饰器
        List<String> readOnly = Collections.unmodifiableList(list);  // 只读装饰器
    }
}
